for n in names:
 v=c['views'][n];r=read['views'][n];p=ROOT/v['PNG_path'];raw=Path(v['EXR_private_path']);cfg=v['config'];assert v['actually_saved']and r['read_by_agent']and r['PNG_sha256']==v['PNG_sha256']==sha(p)and v['EXR_sha256']==sha(raw);actualsize=list(Image.open(p).size);assert actualsize==cfg['resolution_px']and cfg['samples']==96;size=actualsize;assert any('Denoising Albedo' in x for x in v['EXR_channels_actual_header'])and any('Denoising Normal' in x for x in v['EXR_channels_actual_header']);camera=cfg['view'];views.append({'name':n,'camera_location_m':camera['location'],'camera_target_m':camera['target'],'lens_mm':camera['lens'],'PNG_path':v['PNG_path'],'PNG_sha256':v['PNG_sha256'],'EXR_private_path':str(raw),'EXR_sha256':v['EXR_sha256'],'actually_saved':True,'checkpoint_config_sha256':v['config_sha256'],'visual_read_by_agent':True});files.append(p)
report={'source_sha256':c['source_sha256'],'export_sha256':c['export_sha256'],'renderer':'Blender4.3.2 Cycles/OpenImageDenoise CPU','samples':96,'resolution_px':size,'views':views,'derived_from':str((OUT/'render-checkpoints.json').relative_to(ROOT)),'visual_reading_by_agent':str((OUT/'visual-reading.json').relative_to(ROOT)),'art_accepted':False,'physical_iphone_tested':False};(OUT/'render-report.json').write_text(json.dumps(report,indent=2)+'\n');files.append(OUT/'render-report.json')
